    "officialRecord": "Göktepe Savaşı: General Mihail Skobelev komutasındaki Rus birlikleri Türkmenleri yendi. — Göktepe Savaşı (veya Gökdepe), bir Ahal-Teke vahasındaki, Türkmenistan'da, Türkmen hisarı Trans-Hazar demir yolunun üzerinde Aşkabat'ın 45.06 km kuzey batısındaki yerde Ruslar ile Türkmenler arasında yapılan savaştır. Tarihsel olarak bu bilinen tanınmış hisarı 1881 yılında Rus İmparatorluğu ele geçirdi. Gerçek hisar adı olan Yengi Şäher (\"yeni şehir\"), 1878 yılında kuruldu. Aralık 1880'de, General Mihail Dimitriyeviç Skobelev (Rusça: Михаи́л Дми́триевич Ско́белев) komutası altındaki 7,200 kadar Rus, Göktepe'yi kuşattılar...",
    "yasaStory": "괴크테페 전투: 미하일 스코벨레프 장군이 지휘하는 러시아군이 투르크멘군을 격파했습니다.\n\n[역사 상세 기록]\n게오크테페 전투(또는 괵데페 전투)는 투르크메니스탄의 아할-테케 오아시스에 있는 투르크멘 요새에서 아슈하바트의 북서쪽 45.06km 지점에 위치한 트란스카스피 철도 위에서 러시아인과 투르크멘인 사이에 벌어진 전투입니다. 역사적으로 잘 알려진 이 요새는 1881년에 러시아 제국이 점령했습니다. 진짜 요새 이름인 옌기셰헤르(\"새로운 도시\")는 1878년에 세워졌습니다."
