    "officialRecord": "Mersin'in düşman işgalinden kurtuluşu. — Mersin, Türkiye'nin Mersin ilinin merkezi olan şehirdir. Mersin Türkiye'nin Akdeniz Bölgesi'nde bulunan bir liman kentidir. Mersin Limanı Türkiye'nin en büyük limanları arasındadır. Şehirde turizm, sanayi, tarım ve denizcilik gelişmiştir. Mersin'in denizden yüksekliği ortalama 0 metredir. Kentin kuzeyindeki Yumuktepe höyüğünde yapılan kazılarda birçok katman ortaya çıkarılmıştır. Bunların en eskisi, MÖ 6.300'lere, en yenisi ise Selçuklu dönemine tarihleniyor. Kazılardan çıkarılan eserler, Mersin Arkeoloji Müzesi başta...",
