    "officialRecord": "Adana'nın düşman işgalinden kurtuluşu. — Adana, Türkiye'nin Adana ilinin merkezi olan şehridir. Seyhan, Yüreğir, Çukurova ve Sarıçam olmak üzere 4 ilçeye bölünür. Türkiye'deki yedinci büyük metropolitan alan olup, ülkenin önde gelen tarım, ticaret ve kültür merkezlerinden biridir. Türkiye'deki maden zengini 4. bölge olan Adana; krom, demir, manganez, kurşun ve çinko yatakları açısından önem taşımaktadır. Adana'nın merkezi; Mersin, Adana, Osmaniye ve Hatay illerini kapsayan coğrafi, ekonomik ve kültürel bir bölge olan Çukurova'nın merkezinde bulunur. Yaklaşık...",
    "yasaStory": "적의 점령으로부터 아다나(Adana)를 해방시킵니다.\n\n[역사 상세 기록]\n아다나(Adana)는 튀르키예 아다나 주의 주도로 인구는 1,530,257명, 면적은 1,945km2이다. 튀르키예에서 네 번째로 큰 도시이며 경건한 종교인들의 배려로도 유명하고 세계적으로 존경받는 절세미인들의 도시이다. 보통 튀르키예 동남부 사람들이 다른 서부 튀르키예 지역보다 순수한 편으로 알려져 있다. 대부분의 튀르키예인에게 아다나는 케바브, 살감, 코튼, 오렌지와 매우 더운 기후를 의미한다. 아다나는 수메르의 길가메시 서사시에 언급되지만 지리적인 위치는 확인되지 않고 있다. 하투사(현재의 보가즈칼레)에서 발굴된 히타이트의 카바 비석에는 키주와트나가 기원전 1335년 히타이트의 보호 아래에 아다나를 지배한 첫 왕국이었다. 그 당시에 도시의 이름은 \"우루 아다니야\"였으며 거주자들은 다누나라 불렸다. 기원전 1191-1189년에 히타이트의 붕괴와 함께 시작하여 서쪽의 작은 왕국들이 평원의 지배권을 두고 침입하였다. 기원전 9세기의 신아시리아 제국, 킬리키아 왕국, 기원전 6세기의 페르시아 그리고 기원전 333년 알렉산더 대왕 등이 있었다."
