    "officialRecord": "Mustafa Kemal Paşa, İstanbul'daki Divan-ı Harp tarafından idama mahkûm edildi. — Mustafa Kemal Atatürk (1881, Selanik - 10 Kasım 1938, İstanbul), Türk mareşal, devlet adamı, yazar, Türk Kurtuluş Savaşı'nın başkomutanı, Türkiye Cumhuriyeti'nin kurucusu ve ilk cumhurbaşkanıdır. Türkiye'yi laik, sanayileşen bir ulusa dönüştüren kapsamlı ilerici reformlar üstlenmiştir. İdeolojik olarak sekülarist ve milliyetçi politikaları ve sosyo-politik teorileri Kemalizm olarak tanınmıştır. I. Dünya Savaşı sırasında Osmanlı ordusunda görev yapan Atatürk, Çanakkale Cephesi'nde miralaylığa, Sina ve Filistin Cephesi...",
    "yasaStory": "무스타파 케말 파샤(Mustafa Kemal Pasha)는 이스탄불 군사법원에서 사형을 선고받았습니다.\n\n[역사 상세 기록]\n무스타파 케말 아타튀르크(튀르키예어: Mustafa Kemal Atatürk, 1881년 ~ 1938년 11월 10일)는 오스만 제국의 육군 장교, 혁명가, 작가이며 튀르키예 공화국의 건국자이자 초대 대통령이다. 제1차 세계 대전 당시 육군 장교였고, 오스만 제국의 패배 이후 튀르키예 국민 운동 소속으로 튀르키예 독립 전쟁을 주도하였다. 일찍이 청년 투르크 당에서 활동하였으며, 갈리폴리 전투에서 영국과 프랑스 군대의 공세를 저지한 탁월한 장군이기도 하였다. 재임 중인 1938년에 사망하였다. 그의 칭호인 아타튀르크는 \"튀르크의 아버지\"라는 뜻으로, 1934년에 튀르키예 의회가 헌정하였다."
