    "officialRecord": "İzmir'in İtilaf Devletleri tarafından işgalini protesto için Sultanahmet Mitingi yapıldı, mitinge 200 bin kişi katıldı. — İtilaf Devletleri, Anlaşma Devletleri, Müttefik Devletler ya da Müttefikler Britanya İmparatorluğu, Fransa ve Rusya'dan oluşan ittifaktır. I. Dünya Savaşı'ndaki iki ana ittifaktan biridir. İtilaf Devletleri Almanya, Avusturya-Macaristan, Osmanlı İmparatorluğu ve Bulgaristan'ın oluşturduğu İttifak Devletleri'ne karşı savaşmıştır. İtalya önceleri İttifak Devletleri grubunun içerisindeydi fakat 1915'te İtilaf Devletleri'nin yanında savaşa girdi (1915 yılı İtalya'nın savaşa dâhil olduğu yıldır ve İttifak Devletleri'nin...",
    "yasaStory": "연합군의 이즈미르 점령에 항의하는 술탄아흐메트 집회가 열렸으며, 집회에는 20만명이 참석했다.\n\n[역사 상세 기록]\n연합국(영어: Entente Powers)은 제1차 세계 대전 당시 동맹국의 반대 진영에 있던 국가를 말한다. 제1차 세계 대전의 연합국은 프랑스와 러시아 제국, 영국이 독일 제국과 오스트리아-헝가리 제국, 이탈리아 왕국의 삼국 동맹에 대항하기 위해 맺은 삼국 협상을 효시로 하고 있다."
