    "title": "터키 독립 전쟁: 터키군이 그리스 점령 하에 있던 아피온을 탈환했습니다.",
    "source": "위키백과 · 튀르키예 독립 전쟁 (터키 연표)",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%ED%8A%80%EB%A5%B4%ED%82%A4%EC%98%88_%EB%8F%85%EB%A6%BD_%EC%A0%84%EC%9F%81",
    "officialRecord": "Türk Kurtuluş Savaşı: Türk Ordusu, Yunan işgali altında bulunan Afyon'u geri aldı. — Türk Kurtuluş Savaşı (Osmanlıca: قورتولوش صواشى, romanize: Kurtuluş Savaşı), I. Dünya Savaşı'ndan yenik çıkan Osmanlı İmparatorluğu'nun İtilaf Devletleri'nce işgali sonucunda Mîsâk-ı Millî sınırları içinde ülke bütünlüğünü korumak için 1919-1922 yılları arasında gerçekleştirilen çok cepheli siyasi ve askeri mücadeledir. Batı Anadolu'da İtilaf Devletleri'nin harekete geçirdikleri Yunan ordusuna; güneyde Fransız ordusuna; doğuda Ermenistan'ın kuvvetlerine; İstanbul rejimine sadık milislere, feodal güçlere ve ayrılıkçılara...",
    "yasaStory": "터키 독립 전쟁: 터키군이 그리스 점령 하에 있던 아피온을 탈환했습니다.\n\n[역사 상세 기록]\n튀르키예 독립 전쟁(튀르키예어: Kurtuluş Savaşı 쿠르툴루쉬 사와시으[*], 1919년 5월 19일 ~ 1923년 10월 29일)은 제1차 세계 대전에서 오스만 제국이 패배하여 연합국이 오스만 제국의 영토를 분리하려 하는데 반발한 튀르키예 민족주의자들이 일으킨 정치 및 군사적 저항이다. 아나톨리아에서 튀르키예의 민족 운동은 새로운 튀르키예 대국민의회의 창설로 절정에 이르렀는데, 대국민의회는 무스타파 케말의 지도하에 자국의 자원을 성공적으로 동원하였다. 그리스-튀르키예 전쟁, 튀르키예-아르메니아 전쟁, 프랑스-튀르키예 전쟁 이후 튀르키예 혁명주의자들은 1923년 7월에 연합국이 세브르 조약을 폐기하고 새로이 협상하여 로잔 조약을 도출하게끔 하여, 1923년 10월에 아나톨리아와 동트라키아 지방은 튀르키예 공화국의 영토로 보전할 수 있었다. 튀르키예 민족 운동이 성립하면서 오스만 제국의 밀레트 체제가 무너지고, 아타튀르크의 개혁으로 튀르키예에 근대적이고 세속화된 국민 국가가 들어섰다."
