    "officialRecord": "Birinci Balkan Savaşı'nda Osmanlı ve Sırp Orduları arasındaki Kumanova Muharebesi Sırpların galibiyeti ile sonlandı. — Birinci Balkan Savaşı, 7 Ekim 1912-30 Mayıs 1913 tarihleri arasında gerçekleşen, Bulgaristan Krallığı, Sırbistan Krallığı, Yunanistan Krallığı ve Karadağ Krallığı'ndan oluşan Balkan Birliği'nin Osmanlı Devleti'ne karşı başlattığı savaştır. Bu savaş ile Balkan devletleri, Osmanlı Devleti'nin Balkanlardaki topraklarının büyük bir bölümünü ele geçirmiştir. Bu savaş sonucunda Osmanlı Devleti Edirne ve Kırklareli'ye kadar olan Midye-Enez Hattı'nın batısındaki tüm topraklarını Balkan devletlerine vermek zorunda bırakılmıştır.",
    "yasaStory": "제1차 발칸 전쟁에서 오스만군과 세르비아군 사이에 벌어진 쿠마노보 전투는 세르비아군의 승리로 끝났습니다.\n\n[역사 상세 기록]\n제1차 발칸 전쟁(불가리아어: Балканска война; 그리스어: Αʹ Βαλκανικός πόλεμος; 세르비아어: Први балкански рат, 튀르키예어: Birinci Balkan Savaşı, 영어: First Balkan War )은 1912년 10월부터 1913년 5월까지 발발한 전쟁으로 발칸 동맹 국가인 세르비아 왕국, 불가리아 왕국, 그리스 왕국, 몬테네그로 왕국이 오스만 제국에 맞선 전쟁이었다. 1908년 청년 튀르크당 혁명 이후 오스만 제국의 정치는 혼돈을 겪었고, 1912년 알바니아 반란과 이탈리아-튀르크 전쟁으로 오스만 제국의 군대가 그렇게 강력하지 않다는 것을 알게 된 발칸 동맹은 오스만 제국을 상대로 전쟁을 선포했다. 발칸 동맹은 승리를 거두었고, 오스만 제국은 유럽 쪽 영토의 83%와 유럽 쪽 인구의 69%를 잃었다."
