    "officialRecord": "Tekirdağ'ın Malkara ilçesinin kurtuluşu. — Tekirdağ, Türkiye'nin Tekirdağ ilinin merkezi olan şehirdir. 2012 yılında nüfusu 750.000'i geçen 14 adet il TBMM'de kabul edilen kanun ile büyükşehir statüsü kazandığı için Türkiye'nin 30 büyükşehrinden biridir. 30 Mart 2014'te yapılan yerel seçimlerin ardından resmen büyükşehir belediyeciliği ile yönetilmeye başlanmıştır, hizmet sahası 6.190 km² olarak tüm il sınırlarıdır. Bu kanunla üç yeni ilçe kurulmuştur. Bunlar, Süleymanpaşa, Kapaklı ve Ergene'dir. Tekirdağ'ın deniz seviyesinden yüksekliği 37 metredir.",
    "yasaStory": "Tekirdağ의 Malkara 지역 해방.\n\n[역사 상세 기록]\n테키르다(튀르키예어: Tekirdağ, 그리스어: Ραιδεστός, 불가리아어: Родосто)는 튀르키예 북서부에 위치한 도시로, 테키르다 주의 주도이며 인구는 140,535명(2009년 기준)이다. 고대에는 비산티(그리스어: Βισάνθη, Bisanthi)라고 부르기도 했다. 마르마라해 북부 연안과 접하며 이스탄불에서 서쪽으로 135km 정도 떨어진 곳에 위치한다."
