    "officialRecord": "Kanuni Sultan Süleyman, Avusturya seferine çıktı. — I. Süleyman (Osmanlıca: سلطان سليمان اول Sultân Süleymân-ı Evvel, divan edebiyatındaki mahlasıyla Muhibbi; 6 Kasım 1494, Trabzon - 7 Eylül 1566, Zigetvar), Osmanlı İmparatorluğu'nun 10. padişahı ve 89. İslam halifesidir. Batı'da Muhteşem Süleyman, Doğu'da ise adaletli yönetimine atfen Kanûnî Sultan Süleyman (Osmanlıca: قانونى سلطان سليمان) olarak da bilinmektedir. 1520'den 1566'daki ölümüne kadar, yaklaşık 46 yıl boyunca Osmanlı İmparatorluğu'na hükmetti. Toplamda 13 kez sefere çıktı ve saltanatının 10 yıl, 1 ayını...",
    "yasaStory": "Suleiman the Magnificent는 오스트리아로 탐험을 떠났습니다.\n\n[역사 상세 기록]\n쉴레이만 1세(오스만 튀르크어: سليمان, 튀르키예어: I. Süleyman, 1494년 11월 6일 - 1566년 9월 5일)는 오스만 제국의 제10대 술탄이다(재위 1520년 9월 22일 - 1566년 9월 6일). 군사전략가로서의 능력이 뛰어났던 그는 46년이라 긴 치세 동안 세 대륙을 가로지르며 13차례의 대외원정을 실행에 옮겨 수많은 군사적 업적을 쌓음으로써 오스만 제국의 최전성기를 이룩하였다. 서구인들은 그를 ‘장려한 쉴레이만(the Magnificent)’이라는 별명으로 불렸으며, 한국에서는 흔히 ‘쉴레이만 대제’로 번역된다. 터키에서는 법전을 편찬하여 제국의 제도를 정비한 업적을 높이 사 ‘입법자(Kanuni; 아랍어: القانونى al‐Qānūnī)’라는 별명으로 부르고 있다. 그의 이름 쉴레이만은 유대교와 기독교와 더불어 이슬람교에서도 경전으로 추앙받는 구약성서에 기록된 고대 이스라엘의 왕 솔로몬의 튀르키예어식 발음이다."
