    "yasaStory": "훌라구가 바그다드를 점령했다. 바그다드 주민 20만 명이 사망했다.\n\n[역사 상세 기록]\n훌라구 칸(페르시아어: خان هولاكو Hūlākū Khān, 몽골어: ᠬᠦᠯᠡᠭᠦᠬᠠᠨ Hülegü Qan, 旭烈兀, 1218년 ~ 1265년 2월 8일) 혹은 훌레구, 퀴레구(Qülegü)는 몽골 제국의 통치자로 아라비아 반도와 시리아, 남부 이라크를 제외한 서남아시아를 정복한 정복자이자 훌레구 울루스의 초대 한이다. 그는 칭기스 칸의 \"막내\" 아들인 톨루이와 그의 아내인 소르콕타니(Sorqoqtani, 혹은 소르칵타니) 사이에서 난 아들이었다. 그의 형제로는 뭉케와 쿠빌라이, 아리크 부케가 있다. 훌라구의 군대는 서남 아시아의 일부를 몽골 제국의 영토에 편입시켰으며, 쿠빌라이 카안으로부터 페르시아에 울루스를 분봉받았다. 훌라구의 후손들은 사파비 왕조가 출연하기 전까지 이 지역을 다스렸다. 훌라구의 지도력 아래에서 몽골 제국은 이슬람 문명의 가장 위대한 도시라고 할 수 있는 바그다드를 파괴했으며, 다마스쿠스를 굴복시켰다. 이 정복들은 아이유브 왕조가 가지고 있던 시리아와 이집트의 지배권을 맘루크 왕조로 넘어가게 만들었다."
