    "officialRecord": "Tang Hanedanı, Yin Dağları'nda (günümüzde İç Moğolistan) Doğu Göktürk Kağanlığını yendi. — Tang Hanedanı (Çince: 唐朝; Pinyin: Tángcháo) (18 Haziran 618 - 4 Haziran 907), Sui Hanedanı'nın ardından Çin'e hüküm sürmüş hanedandır. 618'de Li Shimin, Sui Hanedanı'nı devirerek Tang Hanedanı'nı kurdu. Li Shimin daha çok Tang Hanedanı'nın kurucusu İmparator Taizong olarak bilinir. Çin imparatorlarının en ünlülerinden biridir. Tang Hanedanı döneminde Çin'in komşularının üzerinde çok büyük etkisi vardı ve birçok komşu krallıkları vergiye bağlamıştı. Bununla birlikte Göktürk Kağanlığı 659 yılında, İkinci Doğu Göktürk...",
    "yasaStory": "당나라는 인산(현재의 내몽골)에서 동투르크 카가나테를 격파했습니다.\n\n[역사 상세 기록]\n당(唐, 618년 ~ 907년)은 수나라와 오대 십국 시대 사이 존재한 중국의 통일왕조다. 수도는 오늘날의 시안인 장안이었다. 초대 황제인 이연은 수 양제의 이종사촌으로, 수나라 말기에 권력을 잡아 수나라를 무너뜨리고 당나라를 건국했다. 7세기와 8세기 기록에 따르면, 당시 정부에 등록된 인구 수는 약 5,000만 명으로 추산한다. 이후 중앙 정부가 붕괴해 인구수를 제대로 조사할 수 없었던 9세기에도 인구 수는 8,000만 명 정도로 증가했다고 추산한다. 이러한 인구수 덕분에 당나라는 중앙아시아를 지배하던 유목민을 상대하기 위해 전문적인 징집병을 양성할 수 있었고, 이를 통해 비단길을 장악할 수 있었다. 수많은 왕조와 국가가 당나라에 조공을 바쳤으며, 일부 지역은 당나라가 정복해서 간접 통치를 했다. 정치적 패권을 달성한 것 이외에도 당나라는 발해, 신라, 베트남, 일본과 같은 동아시아 각국의 문화에도 영향을 미쳤다. 당나라는 오랫동안 안정된 정치를 유지했으나, 안사의 난 이후 중앙집권체계가 쇠퇴하기 시작했다."
