    "yasaStory": "제2차 이뇌뉘 전투에서 터키군의 반격이 시작되었습니다.\n\n[역사 상세 기록]\n제2차 이뇌누 전투는 1921년 3월 23일부터 4월 1일까지 이뇌뉘 근처에서 벌어진 그리스군과 앙카라 정부 사이의 전투입니다. 제1차 이뇌누 전투에서 얻을 수 없었던 터키군을 강화하지 않고 파괴하기 위해, 부르사 지역으로 후퇴한 그리스 제3군단과 우샤크 지역의 제1군단은 1921년 3월 23일 에스키셰히르와 아피온 전략 지역을 점령하고 국민 정부가 세브르 조약의 조항을 수용하도록 강요할 목적으로 전진했습니다."
