    "officialRecord": "Türk Milleti'nin İstiklâl Marşı, TBMM'de kabul edildi. — \"İstiklal Marşı\" (Osmanlıca: استقلال مارشى, romanize: İstiklâl Marşı), Türkiye Cumhuriyeti ve Kuzey Kıbrıs Türk Cumhuriyeti'nin millî marşıdır. Eser, 12 Mart 1921'de Türkiye Büyük Millet Meclisi tarafından resmen kabul edildi. Bu tarih, 29 Ekim 1923'te Cumhuriyet'in ilan edilmesinden yaklaşık iki buçuk yıl öncesine denk geliyordu. Marş, Kurtuluş Savaşı sırasında mücadele eden askerlere moral vermek amacıyla yazılmış bir eser olmasının yanı sıra, henüz kurulmamış olan Cumhuriyet için de ideal bir millî marş niteliği...",
    "yasaStory": "터키 국가의 독립 국가가 터키 대국회에서 승인되었습니다.\n\n[역사 상세 기록]\n독립행진곡(튀르키예어: İstiklâl Marş၊ 이스티클랄 마르시으[*])은 튀르키예와 북키프로스에서 국가로 사용하는 악곡이다. 메흐메트 아키프 에르소이(Mehmet Âkif Ersoy)가 작사하였으며 오스만 제키 윈괴르(Osman Zeki Üngör)가 작곡하였다. 1921년 튀르키예 공화국 국민회의에서 만장일치로 국가로 제정되었는데 제정 당시에 오스만 제국은 그리스 왕국의 침공으로 멸망하기 일보 직전이었다. 1930년에 현재와 같이 변화되었다. 가사는 2절까지 있으며, 원래 이 시는 10절까지 있다."
