    "officialRecord": "Cemal Paşa, Bahriye Nazırlığına getirildi. — Ahmed Cemâl Paşa (6 Mayıs 1872, Midilli - 21 Temmuz 1922, Tiflis), Türk siyasetçi ve asker, İkinci Meşrutiyet döneminde İttihat ve Terakkî Cemiyeti'nin üç liderinden biridir. Özellikle Üç Paşalar İktidarı olarak da bilinen, 1913-1918 yılları arasında Osmanlı İmparatorluğu'nun iç ve dış siyasetinin belirlenmesinde etkin rol oynamıştır. 10 Mart 1914 ve 14 Ekim 1918 tarihleri arasında bahriye nâzırlığı, 5 Ocak 1914 (24 Şubat 1914'e kadar vekâleten) ve 10 Mart 1914 tarihleri arasında ise nâfia nazırlığı görevini üstlenmiştir...",
    "yasaStory": "Cemal Pasha가 해군 장관으로 임명되었습니다.\n\n[역사 상세 기록]\n제말 파샤(오스만 터키어 표기: جمال پاشا, 현대 튀르키예어 표기: Cemal Paşa) 또는 아흐메드 제말(오스만 터키어 표기: احمد جمال, 현대 터키어 표기: Ahmet Cemal; 1872년 5월 6일 출생 - 1922년 7월 21일 별세)은 오스만 제국의 군인이자 정치인이다. 청년 투르크 당에서 활동하였으며, 엔베르 파샤와 탈랏 파샤와 함께 삼두 정치(Three Pashas)의 일원이었다. 제말은 콘스탄티노플의 시장을 역임했다."
