    "yasaStory": "Salih Hulusi Kezrak이 Grand Vizier로 임명되었습니다.\n\n[역사 상세 기록]\nSalih Hulusi (파샤) Kezrak (1864 - 1939), VI. 그는 메흐메드 2세의 통치 기간과 이스탄불이 점령된 기간 동안 1920년 3월 2일부터 1920년 4월 5일까지 28일 동안 대총독을 역임한 체르케스 출신의 오스만 정치가입니다. 그는 1864년 이스탄불에서 태어났습니다. 그는 체르케스 출신입니다. 1888년 5월 30일 현재의 육군사관학교를 우등생으로 졸업하고 참모장이 되었다. 1900년 1월 7일 그는 처음으로 장군으로 진급했다. 1919년에 그는 다마트 페리드 파샤(Damat Ferid Pasha)와 알리 리자 파샤(Ali Rıza Pasha) 정부에서 해군 장관을 역임했습니다."
