    "yasaStory": "Kabataş 남자 고등학교, 술탄 2세. Abdulhamid의 법령에 따라 \"Kabataş Mekteb-i İdâdisi\"라는 이름으로 설립되었습니다.\n\n[역사 상세 기록]\nKabataş Boys' High School은 1908년부터 교육을 제공해 온 투르키예에서 가장 오래된 고등학교 중 하나입니다. 캠퍼스는 이스탄불 오르타쿄이(Ortaköy) 지역의 바닷가에 위치해 있습니다. 터키 공화국 교육부에서 실시하는 고등학교 입학 시험(LGS) 결과에 따라 이 고등학교를 선택하고 합격한 남학생과 여학생은 이 고등학교에 다닐 자격이 있습니다. Kabataş 남자 고등학교에는 현재 900명의 고등학생이 있으며 그 중 약 250명이 기숙 학생입니다. 본관 바로 옆에는 여학생 기숙사, 남학생 기숙사, 식당, 구내식당이 있는 또 다른 기숙사가 있습니다."
