    "officialRecord": "II. Meşrutiyet'in ilanı: 29 yıldır askıda olan Osmanlı Anayasası yeniden yürürlüğe girdi. — İkinci Meşrutiyet (Osmanlıca: ايکنجى مشروطيت), Osmanlı Anayasası'nın, 30 yıl askıda kaldıktan sonra, 23 Temmuz 1908'de yeniden ilan edilmesiyle başlayan ve Mebuslar Meclisi'nin Sultan Vahideddin tarafından 11 Nisan 1920'de tasfiyesi ile sona eren dönemdir. Bu dönemde parlamenter demokrasi, seçim, siyasi parti, askerî darbe ve diktatörlük olgularıyla tanışılmış, iki büyük savaş (Balkan Savaşları ve I. Dünya Savaşı) yaşanmış ve imparatorluğun dağılmasına tanık olunmuştur. Birinci Meşrutiyet resmen sona ermemiş ve yeni...",
    "yasaStory": "II. 입헌군주제 선언: 29년간 정지되었던 오스만 헌법이 다시 발효되었다.\n\n[역사 상세 기록]\n제2차 헌법시대(오스만: ايکنجى مصروتيت)는 1908년 7월 23일 오스만 헌법이 재선포되면서 시작되어 30년 동안 정지되었다가 1920년 4월 11일 술탄 바히데딘에 의해 하원이 해산되면서 끝나는 시기이다. 이 기간 동안 의회 민주주의, 선거, 정당, 군대 쿠데타와 독재가 시작되었고 두 번의 주요 전쟁(발칸 전쟁과 제1차 세계 대전)이 발생했으며 제국이 붕괴되었습니다."
