    "yasaStory": "투르키예 공산당은 공식적으로 앙카라에서 설립되었습니다.\n\n[역사 상세 기록]\n터키공산당(터키공산당)은 독립전쟁 중인 1920년 10월 18일 아타튀르크 명령에 의해 창설된 정당이다. \"공식 공산당\"으로도 알려져 있습니다. 이 결정의 중요한 이유 중 하나는 앙카라 정부와 소련 정부 간의 화해였습니다. 이 기간 동안 소련 정부는 무기와 탄약을 보내 독립전쟁을 지원했다."
