    "officialRecord": "Koca Sinan Paşa, Eflak Seferindeki başarısızlığı nedeniyle azledildi. Yerine Tekeli Lala Mehmed Paşa Sadrazam oldu. Ancak Tekeli Lala Mehmed Paşa'nın 29 Kasım 1595'te ölümü üzerine, 1 Aralık 1595'te beşinci ve son kez tekrar göreve getirilecekti. — Koca Sinan Paşa (Arnavutça: Sinan Pasha Topojani; 1520 - 3 Nisan 1596, İstanbul), III. Murad ve III. Mehmed'in saltanat dönemlerinde beş kez olmak üzere toplam 8 yıl 5 ay sadrazamlık yapmış Osmanlı komutanı ve devlet adamıdır. Arnavut asıllı olan Paşa, Enderûn'da yetişmiş ve Yemen ile Tunus'u Osmanlı topraklarına katması sebebiyle bu bölgelerin fatihi olarak anılmıştır Dört padişahın döneminde çeşitli görevlerde bulunmuş olan Sinan Paşa, Kanuni Sultan Süleyman'ın çaşnigirbaşısıyken önce Malatya Sancakbeyi olarak saraydan...",
    "yasaStory": "코카 시난 파샤는 왈라키아 탐험에 실패하여 해고되었습니다. Tekeli Lala Mehmed Pasha가 그의 자리를 대신하여 Grand Vizier가 되었습니다. 그러나 1595년 11월 29일 테켈리 랄라 메흐메드 파샤(Tekeli Lala Mehmed Pasha)가 사망하자 그는 1595년 12월 1일에 다섯 번째이자 마지막으로 재임명되었습니다.\n\n[역사 상세 기록]\n코카 시난 파샤(알바니아어: Sinan Pasha Topojani, 1520년 - 1596년 4월 3일, 이스탄불), III. 무라드와 III. 그는 메흐메드 통치 기간 동안 5번, 총 8년 5개월 동안 대총독을 역임한 오스만 제국의 사령관이자 정치가입니다. 알바니아 출신인 파샤는 엔데룬에서 자랐으며 예멘과 튀니지를 오스만 제국에 합병했기 때문에 이 지역의 정복자로 알려졌습니다. 4명의 술탄 통치 기간 동안 다양한 직위를 역임한 시난 파샤는 술레이만 대제의 수석 맛관이었으며, 말라티아 산카베이(Malatya Sancakbeyi)로 먼저 궁전을 떠났습니다."
