    "officialRecord": "Florence Nightingale Hastanesine adını veren hemşire, Üsküdar'daki Selimiye Kışlası'nda, Kırım Savaşı sırasında yaralanan İngiliz askerlerinin tedavi ve bakımını yapmıştır. — Florence Nightingale (İngilizce telaffuz: [ˈflɒrəns_ˈnaɪtɨŋɡeɪl]; 12 Mayıs 1820 – 13 Ağustos 1910), İngiliz sosyal reformcu, istatistikçi ve hemşiredir. Modern hemşireliğin kurucusudur. Kırım Savaşı sırasında eğitim alan hemşirelerin yöneticisi olarak öne çıkmış, savaşta yaralanan askerlerin tedavi ve bakımlarını yapmıştır. Hemşireliğe son derece olumlu bir itibar kazandırmış ve Viktorya kültüründe bir ikon olmuştur. Özellikle gece gündüz demeden yaralı askerlere baktığı için kendisine \"Lambalı Kadın\" denmiştir. Bazı...",
    "yasaStory": "플로렌스 나이팅게일 병원의 이름을 딴 간호사는 위스퀴다르의 셀리미예 병영에서 크림 전쟁 중 부상을 입은 영국군 병사들을 치료하고 돌보았습니다.\n\n[역사 상세 기록]\n플로렌스 나이팅게일(영어: Florence Nightingale, 1820년 5월 12일~1910년 8월 13일)은 영국의 간호사, 작가, 통계학자이다. 잉글랜드 성공회의 성인이기도 하며, 성공회에서는 8월 13일을 나이팅게일의 축일로 지키고 있다. 그녀는 크림 전쟁 동안 종군 간호사로 일함으로써 간호사라는 직업을 널리 알렸다."
