    "officialRecord": "Osmanlı Rus Savaşı: Rus ordusu 5 aydır süren kuşatma sonrası Plevne'yi aldı. — Plevne Savunması (Rusça: Осада Плевны, romanize: Osada Plevnı veya Осада Плевена, romanize: Osada Plevena; lit. \"Plevne Kuşatması\"); 93 Harbi sırasında Plevne kentinin Rus İmparatorluk Ordusu tarafından kuşatılmasının ardından, kentin Gazi Osman Paşa komutası altındaki Osmanlı Ordusu tarafından Rus ve daha sonra Rumen taarruzlarına karşı 19 Temmuz ve 10 Aralık 1877 arasında 145 gün boyunca savunmasıyla gerçekleşen, 93 Harbi'nin en önemli muharebelerinden biridir. Osmanlı Ordusu, 145 gün boyunca sayıca kendisinden kalabalık...",
