    "officialRecord": "Türkiye İşçi ve Çiftçi Sosyalist Fırkası kuruldu. — Türkiye İşçi ve Çiftçi Sosyalist Fırkası (TİÇSF), Osmanlı Devleti'nde Mütareke döneminde kurulan sol görüşlü siyasi örgüt. 20 Eylül 1919 tarihinde İstanbul'da kuruldu. Bir aydınlar fırkası olan TÇİSF, III. Enternasyonal'e bağlı, Marksist-Leninist bir örgüttü. Genel sekreteri Dr. Şefik Hüsnü idi. Fırkanın kurucu kadrosunda Ethem Nejat, Ahmet Akif, Sadrettin Celal, Vedat Nedim, Nurullah Esat ve Namık İsmail bulunuyordu. Temelde işçi sınıfının hak ve özgürlüklerini savunan Parti, Kurtuluş Savaşı yıllarında Kemalistlerin...",
