    "officialRecord": "&ndash; Bari, the last Byzantine possession in southern Italy, is surrendered to the Norman Robert Guiscard. — Bari ( BAR-ee; Italian: [ˈbaːri] ; Barese: Bare [ˈbæːrə]; Latin: Barium) is the capital city of the Metropolitan City of Bari and of the region of Apulia, on the Adriatic Sea in southern Italy. It is one of the most important economic centres of mainland southern Italy. It is a port and university city as well as the city of Saint Nicholas. The city itself is the 9th-largest city in Italy with a population of 316,248, while the urban area has approximately 750,000 inhabitants. Its metropolitan province is the 5th-largest...",
    "yasaStory": "– 이탈리아 남부의 마지막 비잔틴 영토였던 바리(Bari)가 노먼 로베르트 기스카르(Robert Guiscard)에게 항복합니다.\n\n[역사 상세 기록]\n바리(이탈리아어: Bari, 이탈리아어 발음: [ˈbaːri] ( ), 바리어 오류: {{IPA}}: unrecognized language tag: bare; 라틴어: Barium)는 바리 광역시 및 풀리아 지역의 핵심 도시이며, 남부 이탈리아 아드리아해에 위치했다. 남부 이탈리아의 본토 지역 내 가장 중요한 경제 중심지 중 한 곳이다. 항구 및 대학 도시이며 성 니콜라오스를 수호성인으로 삼고 있다. 면적 116 제곱킬로미터 (45 mi2)가 넘는 바리 자체 인구는 315,473명이며, 대도시권에서는 인구가 750,000명이다. 광역권 내에는 120만 명에 이른다. 바리는 네 개 도시 구역으로 이뤄져 있다. 북쪽에는 현대식 항구 두 곳 사이 반도에 자리한 밀집된 구도심이 있으며, 이곳에는 성 니콜라 대성당, 산 사비노 대성당 (1035년~1171년), 그리고 현재는 주요 야간 명소 역할을 하기도 하는 노르만-슈바벤 성이 있다."
