    "yasaStory": "– 테오도라는 비잔틴 황후로 즉위하고 하기아 소피아에서 테오필로스 황제와 결혼합니다. 그녀는 기독교 정통과 아이콘을 복원한 것으로 알려져 있습니다.\n\n[역사 상세 기록]\n테오도라(그리스어: Θεοδώρα; c. 815 – c. 867)는 때때로 아르메니아인 테오도라 또는 축복받은 테오도라라고도 불리며 830년부터 842년까지 비잔틴 황제 테오필로스의 아내였던 비잔틴 황후였습니다. 테오필로스가 죽은 후 미망인인 테오도라는 아들이 폐위될 때까지 부부의 어린 아들 미카엘 3세의 섭정으로 활동했습니다. 856년 그녀. 830년에 테오도라는 테오필로스와 결혼하여 비잔틴 황후 배우자가 되었고 7명의 자녀를 낳았습니다. 우상 숭배자였던 테오도라는 우상 파괴자인 남편과 대조적인 신념을 갖고 있었습니다."
