    "yasaStory": "– 콘스탄티누스 5세 황제의 비잔틴 군대가 안키알루스 전투에서 불가리아 군대를 격파했습니다.\n\n[역사 상세 기록]\n콘스탄티누스 5세(그리스어: ΚΩνσταντῖνος, 로마자 표기: Kōnstantīnos, 718년 7월 – 775년 9월 14일)는 741년부터 775년까지의 비잔틴 황제였습니다. 그의 통치 기간 동안 외부 위협으로부터 비잔틴 안보가 강화되었습니다. 유능한 군사 지도자로서 콘스탄틴은 이슬람 세계의 내전을 이용하여 아랍 국경에 제한적인 공격을 가했습니다. 동부 국경이 확보되자 그는 발칸 반도의 불가르족을 상대로 반복적인 작전을 수행했습니다."
