    "yasaStory": "– 비잔틴 황제 필리피쿠스는 트라키아에서 옵시키온 군대의 공모자들에 의해 눈이 멀게 되고 폐위되고 유배됩니다. 그는 비잔틴 군대의 재편성을 시작한 아나스타시오스 2세(Anastasios II)의 뒤를 이었습니다.\n\n[역사 상세 기록]\nPhilippicus(라틴어: Filepicus; 그리스어: Φιλιππικός, 로마자 표기: Philippikós), 태어난 Bardanes(그리스어: Βαρδάνις, 로마자 표기: Bardánēs; 아르메니아어: Ҏ֡ր֤֡ר, Vardan)는 711년부터 713년까지 비잔틴 황제였습니다. 그는 인기 없는 세력에 맞서 쿠데타를 벌여 권력을 잡았습니다. 두 번째 재위기간(705~711)은 공포정치였던 유스티니아누스 2세 황제. 빌립보의 통치는 짧았으며 왕위에 오르면서 시행된 그의 두 가지 정책은 대중의 표를 얻지 못했습니다. 그의 증언은 백작이 고안한 음모의 결과였습니다."
