    "yasaStory": "– 비잔틴 장군 Isaac Komnenos가 통치 중인 황제 Michael VI Bringas에 맞서 비잔틴 황제로 선포되었습니다.\n\n[역사 상세 기록]\n이삭 1세 콤네노스(고대 그리스어: Ἰσαάκιος Κομννός, 로마자 표기: Isaákios Komnēnós; 1007년경 – 1060년 6월 1일)는 1057년부터 1059년까지 비잔틴 제국의 황제였으며, 콤네니아 왕조의 첫 번째 통치 구성원이었습니다. 마누엘 에로티코스 콤네노스(Manuel Erotikos Komnenos) 장군의 아들로 어려서 고아가 되었고 바실리우스 2세(Basil II) 황제의 보살핌을 받으며 자랐다. 그는 c.에서 동부 군대의 총사령관을 역임하면서 성공적인 군 사령관으로 이름을 올렸습니다. 1042년과 1054년. 1057년에 그는 음모의 우두머리가 되었습니다."
