    "yasaStory": "– 비잔틴 황제 미카엘 1세는 음모의 위협을 받고 그의 장군인 아르메니아인 레오에게 양위하고 수도사가 되었습니다(아타나시우스라는 이름으로).\n\n[역사 상세 기록]\n미카엘 1세 랑가베(Rhangabe라고도 함, 그리스어: Μιχαὴλ Α' Ῥαγκαβές, 로마자 표기: Mikhaḗl 1 Rhangkabés; c. 770 – 844년 1월 11일)는 811년부터 813년까지의 비잔틴 황제였습니다. Bulgars에 대한 비참한 캠페인에서 살아 남았고 심각한 부상을 입은 Staurakios (r. 811–811)보다 제국의 후계자로 선호되었습니다. 그는 811년 10월 2일 콘스탄티노폴리스 총대주교 니케포루스 1세에 의해 황제로 선포되었습니다. 미카엘의 정책은 대체로 화해적이었고, 그는 압도적으로 우호적이었습니다."
