    "yasaStory": "– 콘스탄티누스 11세가 미스트라스에서 비잔틴 황제로 즉위합니다.\n\n[역사 상세 기록]\n콘스탄티누스 11세 드라가세스 팔라이올로고스 또는 드라가시 팔라이올로고스(그리스어: ΚΩνσταντῖνος Δραγάσις Παλαιολόγος, 로마자 표기: Kōnstantīnos Dragásēs Palaiológos, 1404년 2월 8일 ~ 1453년 5월 29일)는 비잔티움 제국의 마지막 황제이다. 1449년 1월 23일, 1453년 5월 29일 콘스탄티노플이 함락된 전투에서 사망할 때까지. 콘스탄티누스의 죽음은 동로마 제국의 결정적인 종말을 의미했으며, 그 기원은 콘스탄티누스 대제가 330년에 로마 제국의 새로운 수도로 콘스탄티노플을 건립한 때까지 거슬러 올라갑니다."
