    "yasaStory": "– 이브라힘 파샤 휘하의 이집트 군대가 5개월 간의 포위 공격 끝에 오스만 제국으로부터 아크레를 점령했습니다.\n\n[역사 상세 기록]\n이브라힘 파샤(아랍어: إبراهيم باسا Ibrāhīm Bāshā, 1789년 – 1848년 11월 10일)는 이집트의 장군이자 정치인이었습니다. 그는 이집트와 오스만 군대의 사령관이자 무함마드 알리, 오스만 왈리, 그리고 알려지지 않은 이집트와 수단의 케디브의 장남이었습니다. 그는 무하마드 알리 왕조 이후 이집트의 두 번째 통치자였으며 1848년 7월 20일부터 1848년 11월 10일까지 통치했습니다. 이브라힘은 그의 아버지가 통치 기간 동안 창설한 이집트 군대의 장군으로 복무했으며 이집트 군대의 첫 번째 지휘권을 맡았습니다."
