    "yasaStory": "– 안드라소스 전투: 레오 포카스(Leo Phokas the Younger) 휘하의 비잔틴군이 알레포의 함다니드 에미르인 사이프 알 다울라(Sayf al-Dawla)에게 압도적인 승리를 거두었습니다.\n\n[역사 상세 기록]\n안드라소스 전투(Battle of Andrassos 또는 Adrassos)는 960년 11월 8일 레오 포카스가 이끄는 비잔틴군과 에미르 사이프 알 다울라가 이끄는 함다니드 알레포 토후국의 군대 사이에서 벌어졌습니다. 그것은 타우루스 산맥(Taurus Mountains)의 미확인 산길에서 싸웠습니다. 사이프 알 다울라(Sayf al-Dawla)는 945년 알레포에 기반을 둔 토후국을 세웠고, 빠르게 동부 국경에서 비잔틴 제국의 주요 무슬림 적대자로 떠올랐습니다. 양측은 번갈아 성공하면서 습격과 반격을 시작했습니다."
